<script setup>
import { ref } from 'vue'; import { Head, Link } from '@inertiajs/vue3'; import { ArrowLeft, Heart, MapPin, Star, PackageCheck, CheckCircle2, Layers3 } from 'lucide-vue-next'; import ProductCard from '../../Components/ProductCard.vue';
const props=defineProps({product:Object,related:Array}); const saved=ref(JSON.parse(localStorage.getItem('source-x-saved')||'[]')); const toggle=()=>{saved.value=saved.value.includes(props.product.id)?saved.value.filter(x=>x!==props.product.id):[...saved.value,props.product.id];localStorage.setItem('source-x-saved',JSON.stringify(saved.value));};
</script>
<template><Head :title="product.name"/><div class="app-shell"><header class="topbar"><div class="container nav"><Link href="/" class="brand"><span class="brand-mark">SX</span><span>Source X</span></Link><span class="nav-label">Smart Product Discovery</span></div></header><main class="container detail-page"><Link href="/" class="back-link"><ArrowLeft :size="16"/> Back to discovery</Link><div class="detail-card"><div class="detail-image"><img :src="product.image" :alt="product.name"></div><div class="detail-content"><div class="eyebrow"><span>{{product.category}}</span><span>•</span><span>{{product.type}}</span></div><h1>{{product.name}}</h1><p class="source">Sourced from <strong>{{product.source_name}}</strong> · <MapPin :size="15"/> {{product.location}}</p><div class="detail-rating"><Star :size="16" fill="currentColor"/> {{product.rating}} <span>{{product.review_count}} reviews</span></div><p class="detail-description">{{product.description}}</p><div class="detail-price">{{product.formatted_price}} <small>/ {{product.unit}}</small></div><div class="detail-availability" :class="product.is_available?'available':'unavailable'"><PackageCheck :size="18"/> {{product.is_available?`${product.stock} units currently available`:'Currently out of stock'}}</div><div class="detail-actions"><button class="save-large" :class="{saved:saved.includes(product.id)}" @click="toggle"><Heart :size="18" :fill="saved.includes(product.id)?'currentColor':'none'"/> {{saved.includes(product.id)?'Saved':'Save product'}}</button><Link href="/" class="discover-btn">Continue discovering</Link></div><div class="trust-row"><span><CheckCircle2 :size="16"/> Verified listing</span><span><CheckCircle2 :size="16"/> Source information</span></div></div></div><section v-if="related.length" class="detail-related"><div class="section-heading"><div><p class="kicker"><Layers3 :size="15"/> SIMILAR PRODUCTS</p><h2>You may also discover</h2></div></div><div class="product-grid"><ProductCard v-for="item in related" :key="item.id" :product="item" :saved="saved.includes(item.id)" @toggle-save="toggle"/></div></section></main></div></template>
